import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"8、【比】 坤下坎上","description":"温公易说 - 8、【比】 坤下坎上","frontmatter":{"title":"8、【比】 坤下坎上","description":"温公易说 - 8、【比】 坤下坎上"},"headers":[],"relativePath":"zh/classics/wengong/009.md","filePath":"zh/classics/wengong/009.md"}'),n={name:"zh/classics/wengong/009.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_8、【比】-坤下坎上" tabindex="-1">8、【比】 坤下坎上 <a class="header-anchor" href="#_8、【比】-坤下坎上" aria-label="Permalink to “8、【比】 坤下坎上”">​</a></h1><h3 id="彖曰-比-吉也-比-辅也。下顺从也。原筮-元永贞-无咎-以刚中也。不寜方来-上下应也。后夫凶-其道穷也。" tabindex="-1">彖曰：比，吉也，比，辅也。下顺从也。原筮，元永贞，无咎，以刚中也。不寜方来，上下应也。后夫凶，其道穷也。 <a class="header-anchor" href="#彖曰-比-吉也-比-辅也。下顺从也。原筮-元永贞-无咎-以刚中也。不寜方来-上下应也。后夫凶-其道穷也。" aria-label="Permalink to “彖曰：比，吉也，比，辅也。下顺从也。原筮，元永贞，无咎，以刚中也。不寜方来，上下应也。后夫凶，其道穷也。”">​</a></h3><p>比吉，比之所以吉者何？杂卦曰：比乐，师忧。凡物，孤则危，群则强。比者，上下相亲，他不能间，外不能侵者也。故吉。原筮者何？比者，不可茍合也。是故。初六曰：有孚，比之，无咎。夫初六比之始也，始谋相亲者，不可不谨择其人。人之诚信未孚而亲爱之，取祸之道也。故曰：有孚，比之，无咎。系辞曰：君子易其心而后语，定其交而后求，此之谓也。原筮，元永贞，无咎者何？凡比之道，不可以不善也，不可以不长也，不可以不正也。故曰：原筮，元永贞，无咎。夫物比而不以刚中，则柔邪也。故彖曰：原筮，元永贞，无咎，以刚中也。</p><h3 id="象曰-地上有水-比。先王以建万国-亲诸侯。" tabindex="-1">象曰：地上有水，比。先王以建万国，亲诸侯。 <a class="header-anchor" href="#象曰-地上有水-比。先王以建万国-亲诸侯。" aria-label="Permalink to “象曰：地上有水，比。先王以建万国，亲诸侯。”">​</a></h3><h3 id="初六-有孚-比之-无咎。有孚盈缶-终来有他吉。-象曰-比之初六-有他吉也。" tabindex="-1">初六：有孚，比之，无咎。有孚盈缶，终来有他吉。 象曰：比之初六，有他吉也。 <a class="header-anchor" href="#初六-有孚-比之-无咎。有孚盈缶-终来有他吉。-象曰-比之初六-有他吉也。" aria-label="Permalink to “初六：有孚，比之，无咎。有孚盈缶，终来有他吉。 象曰：比之初六，有他吉也。”">​</a></h3><h3 id="六二-比之-自内-贞吉。-象曰-比之自内-不自失也。" tabindex="-1">六二：比之，自内，贞吉。 象曰：比之自内，不自失也。 <a class="header-anchor" href="#六二-比之-自内-贞吉。-象曰-比之自内-不自失也。" aria-label="Permalink to “六二：比之，自内，贞吉。 象曰：比之自内，不自失也。”">​</a></h3><h3 id="六三-比之匪人。-象曰-比之匪人-不亦伤乎" tabindex="-1">六三：比之匪人。 象曰：比之匪人，不亦伤乎？ <a class="header-anchor" href="#六三-比之匪人。-象曰-比之匪人-不亦伤乎" aria-label="Permalink to “六三：比之匪人。 象曰：比之匪人，不亦伤乎？”">​</a></h3><h3 id="六四-外比之-贞吉。-象曰-外比于贤-以从上也。" tabindex="-1">六四：外比之，贞吉。 象曰：外比于贤，以从上也。 <a class="header-anchor" href="#六四-外比之-贞吉。-象曰-外比于贤-以从上也。" aria-label="Permalink to “六四：外比之，贞吉。 象曰：外比于贤，以从上也。”">​</a></h3><p>外比者，何弃亲而从疏也？弃亲而从疏者，非亲贤而从上，则不可也。亲贤而从上者，茍不出乎正，犹不免乎凶也。夫比，非大公之道也。子曰：君子周而不比，小人比而不周。故比而不中正者，皆非君子之道也。</p><h3 id="九五-显比-王用三驱-失前禽-邑人不诫-吉。-象曰-显比之吉-位正中也。舍逆取顺-失前禽也。邑人不诫-上使中也。" tabindex="-1">九五：显比，王用三驱，失前禽，邑人不诫，吉。 象曰：显比之吉，位正中也。舍逆取顺，失前禽也。邑人不诫，上使中也。 <a class="header-anchor" href="#九五-显比-王用三驱-失前禽-邑人不诫-吉。-象曰-显比之吉-位正中也。舍逆取顺-失前禽也。邑人不诫-上使中也。" aria-label="Permalink to “九五：显比，王用三驱，失前禽，邑人不诫，吉。 象曰：显比之吉，位正中也。舍逆取顺，失前禽也。邑人不诫，上使中也。”">​</a></h3><p>九五显比吉何也？九五履至贵之位，为众阴所归，畅其中正以怀海内。从命者赏，违命者诛。善善恶恶而不在于私，用中正以求比者也。故曰：显比吉。显者，光显盛大之谓也。王用三驱，失前禽者何？背去之禽也。失者何？求与之相亲而不可得者也。</p><h3 id="上六-比之无首-凶。-象曰-比之无首-无所终也。" tabindex="-1">上六：比之无首，凶。 象曰：比之无首，无所终也。 <a class="header-anchor" href="#上六-比之无首-凶。-象曰-比之无首-无所终也。" aria-label="Permalink to “上六：比之无首，凶。 象曰：比之无首，无所终也。”">​</a></h3>',12)])])}const m=e(n,[["render",l]]);export{b as __pageData,m as default};
